        const byMenuButton=document.querySelector('#by-menu'),byNav=document.querySelector('#by-nav');byMenuButton.addEventListener('click',()=>{const open=byMenuButton.getAttribute('aria-expanded')==='true';byMenuButton.setAttribute('aria-expanded',String(!open));byMenuButton.setAttribute('aria-label',open?'Buka menu':'Tutup menu');byNav.classList.toggle('open',!open)});byNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{byNav.classList.remove('open');byMenuButton.setAttribute('aria-expanded','false');byMenuButton.setAttribute('aria-label','Buka menu')}));
        const bySafe=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;node.textContent=text;return node},byMoney=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0);const byBudgetYear=document.querySelector('#by-budget-year'),byBudgetList=document.querySelector('#by-budget-list'),byBudgetLabel=document.querySelector('#by-budget-year-label');fetch('/api/desa/banyuanyar-lor/budgets').then(response=>response.ok?response.json():Promise.reject()).then(budgets=>{if(!budgets.length)return;byBudgetYear.hidden=false;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);byBudgetYear.append(option)});const render=()=>{const budget=budgets.find(item=>String(item.year)===String(byBudgetYear.value));if(!budget)return;byBudgetLabel.textContent=String(budget.year);byBudgetList.replaceChildren();[['Dana Desa',budget.villageFund],['Alokasi Dana Desa',budget.villageAllocation],['Bagi Hasil Pajak',budget.taxRevenueShare],['Bagi Hasil Retribusi',budget.retributionShare]].forEach(([label,value])=>{const row=document.createElement('div');row.className='by-budget-row';row.append(bySafe('span','',label),bySafe('strong','',value?byMoney(value):'Belum tersedia'));byBudgetList.append(row)})};byBudgetYear.value=String(budgets[0].year);byBudgetYear.addEventListener('change',render);render()}).catch(()=>{});
        const byFilters=document.querySelector('#by-filters'),byProjectList=document.querySelector('#by-project-list'),byYear=document.querySelector('#by-filter-year'),byStatus=document.querySelector('#by-filter-status'),byLocation=document.querySelector('#by-filter-location');let byProjects=[];function byRenderProjects(){const filters=[['year',byYear.value],['status',byStatus.value],['location',byLocation.value]],visible=byProjects.filter(project=>filters.every(([key,value])=>!value||String(project[key]||'')===value));byProjectList.replaceChildren();if(!visible.length){byProjectList.append(bySafe('p','by-project-empty','Belum ada informasi pembangunan yang dapat ditampilkan.'));return}visible.forEach((project,index)=>{const row=document.createElement('article');row.className='by-project';row.append(bySafe('span','by-project-number',String(index+1).padStart(2,'0')));const content=document.createElement('div'),meta=document.createElement('div');meta.className='by-project-meta';[project.year,project.location,project.status].filter(Boolean).forEach(value=>meta.append(bySafe('span','',String(value))));content.append(meta,bySafe('h3','',project.title||'Kegiatan desa'),bySafe('p','',project.summary||'Rincian belum tersedia.'));const end=document.createElement('div');end.className='by-project-end';end.append(bySafe('strong','',project.funding||'Anggaran belum tersedia'));const detail=bySafe('button','by-project-detail','Rincian pekerjaan');detail.type='button';end.append(detail);row.append(content,end);const overlay=document.createElement('div');overlay.className='by-project-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-label',`Rincian ${project.title||'pekerjaan'}`);const head=document.createElement('div');head.className='by-overlay-head';head.append(bySafe('strong','','Rincian pekerjaan'));const close=bySafe('button','by-overlay-close','');close.type='button';close.setAttribute('aria-label','Tutup rincian');close.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg>';close.addEventListener('click',()=>overlay.classList.remove('open'));head.append(close);overlay.append(head);[['Lokasi',project.location],['Tahun',project.year],['Status',project.status],['Rincian',project.details],['Volume',project.volume],['Sumber dana',project.funding],['Pelaksana',project.executor],['Jadwal',project.schedule],['Progres fisik',project.progress==null?'':`${project.progress}%`],['Realisasi belanja',project.spent?byMoney(project.spent):''],['Sumber informasi',project.source]].forEach(([label,value])=>{if(value!==undefined&&value!==null&&value!==''){const item=document.createElement('div');item.className='by-overlay-row';item.append(bySafe('span','',label),bySafe('strong','',String(value)));overlay.append(item)}});if(project.sourceUrl){const source=document.createElement('a');source.href=project.sourceUrl;source.target='_blank';source.rel='noopener noreferrer';source.className='by-project-detail';source.textContent='Buka sumber informasi';overlay.append(source)}detail.addEventListener('click',()=>overlay.classList.add('open'));row.append(overlay);byProjectList.append(row)})}fetch('/api/desa/banyuanyar-lor/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>{byProjects=Array.isArray(data.projects)?data.projects:[];if(!byProjects.length){byRenderProjects();return}[["year",byYear],["status",byStatus],["location",byLocation]].forEach(([key,select])=>{[...new Set(byProjects.map(project=>String(project[key]||'')).filter(Boolean))].sort().forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)})});byFilters.hidden=false;byFilters.addEventListener('change',byRenderProjects);byFilters.addEventListener('reset',event=>{event.preventDefault();[byYear,byStatus,byLocation].forEach(select=>select.value='');byRenderProjects()});byRenderProjects()}).catch(()=>{});
        const byQuestions=[{key:'title',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',prompt:'Kontak yang bisa dihubungi (opsional).',required:false,type:'text'}];let byAnswers={},byStep=0;const byChat=document.querySelector('#by-chat'),byMessages=document.querySelector('#by-chat-messages'),byControls=document.querySelector('#by-chat-controls'),byActions=document.querySelector('#by-chat-actions'),byError=document.querySelector('#by-chat-error'),byToggle=document.querySelector('#by-chat-toggle');function bySay(text,user=false){byMessages.append(bySafe('div',`by-chat-message${user?' is-user':''}`,text));byChat.querySelector('.by-chat-body').scrollTop=byChat.querySelector('.by-chat-body').scrollHeight}function byAction(label,handler,primary=false){const button=bySafe('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function byCloseChat(reset=true){byChat.classList.remove('open');byChat.setAttribute('aria-hidden','true');byToggle.setAttribute('aria-expanded','false');if(reset){byAnswers={};byStep=0;byMessages.replaceChildren();byControls.replaceChildren();byActions.replaceChildren();byError.textContent=''}}function byRenderQuestion(){byControls.replaceChildren();byActions.replaceChildren();byError.textContent='';if(byStep>=byQuestions.length){bySay('Periksa kembali usulan sebelum dikirim.');bySay(`${byAnswers.title}\n${byAnswers.location}\n${byAnswers.description}`);byActions.append(byAction('Batal',()=>byCloseChat()),byAction('Kirim usulan',bySubmitProposal,true));return}const question=byQuestions[byStep];bySay(question.prompt);byControls.append(bySafe('div','by-chat-prompt',`${byStep+1} dari ${byQuestions.length}`));if(question.type==='choice'){const options=document.createElement('div');options.className='by-chat-options';question.options.forEach(option=>options.append(byAction(option,()=>{byAnswers[question.key]=option;bySay(option,true);byStep++;byRenderQuestion()})));byControls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='by-chat-input';input.placeholder=question.key==='title'?'Judul usulan':question.key==='location'?'Lokasi':question.key==='description'?'Uraian singkat':question.key==='name'?'Nama':'Kontak';input.setAttribute('aria-label',input.placeholder);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;byControls.append(input)}byActions.append(byAction('Batal',()=>byCloseChat()));if(!question.required)byActions.append(byAction('Lewati',()=>{byAnswers[question.key]='';byStep++;byRenderQuestion()}));byActions.append(byAction(byStep===byQuestions.length-1?'Tinjau':'Lanjut',()=>{const input=byControls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){byError.textContent='Bagian ini perlu diisi.';return}byAnswers[question.key]=value;if(value)bySay(value,true);byStep++;byRenderQuestion()},true))}async function bySubmitProposal(){byError.textContent='';const submit=byActions.querySelector('.primary');submit.disabled=true;try{const response=await fetch('/api/desa/banyuanyar-lor/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...byAnswers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');byMessages.replaceChildren();byControls.replaceChildren();byActions.replaceChildren();bySay(result.message||'Usulan berhasil dikirim.');byActions.append(byAction('Selesai',()=>byCloseChat(),true))}catch(exception){byError.textContent=exception.message;submit.disabled=false}}byToggle.addEventListener('click',()=>{const open=!byChat.classList.contains('open');byChat.classList.toggle('open',open);byChat.setAttribute('aria-hidden',String(!open));byToggle.setAttribute('aria-expanded',String(open));if(open&&!byMessages.childElementCount)byRenderQuestion()});document.querySelector('#by-chat-close').addEventListener('click',()=>byCloseChat(false));
    </script>
    @include('desa.partials.managed-content')
    @include('desa.partials.responsive')
</body>
</html>
